"use strict";

// A SECOND installed instance of fixture-lib, same name and same version as
// the top-level one. Unlike that instance, this one's `parse` export has
// real provenance -- the right-hand side IS the function node -- and is
// genuinely reached from the entrypoint.
//
// It exists to make cross-instance borrowing observable: the top-level
// instance's `parse` is unattributable, and if attribution were not scoped
// per PackageInstance it would find this reachable node instead and report
// a confident AFFECTED against the wrong install.
exports.parse = function (input) {
  return "nested:" + String(input);
};
